  "blastIntro": {
    "id": "article7-2",
    "title": "爆裂進化的發動條件",
    "gid": 1083275855,
    "row": 2,
    "paragraphs": [
      {
        "text": "何謂「爆裂進化」?",
        "row": 2
      },
      {
        "text": "Ver 3.0限定的爆裂進化功能，可以讓你的數碼獸在戰鬥或訓練過程中暫時進化至更高階段(一到兩級)。",
        "row": 4
      },
      {
        "text": "爆裂進化有兩種類型",
        "row": 5
      },
      {
        "text": "[橙光爆裂進化]\n在爆裂持續時間內暫時提升數碼獸進化階段一級。",
        "row": 6
      },
      {
        "text": "[綠光爆裂進化]\n如顯示「Blast-Evolution」字樣：\n高機率會在戰鬥中進化 2次\n如果顯示“Blast-Evolution MAXIMUM”：\n100%會在戰鬥中進化 2次",
        "row": 6
      },
      {
        "text": "發動條件：橙光爆裂進化會在數碼獸略微飽腹且 XAI 等級為空或半滿時隨機觸發。",
        "row": 9
      },
      {
        "text": "發動條件：需要飽滿度且強度滿格，XAI 等級為滿，且勝率達 70%。(如沒有綠光，則進化是隨機的。)",
        "row": 9
      },
      {
        "text": "*如果你的數碼獸已戰鬥滿100次，則每次都能發動爆發進化。",
        "row": 10
      },
      {
        "text": "備註：D-Cyber V3 沒有配備橙／綠狀態指示燈，故爆裂進化是否成功僅能於對戰過程中確認。",
        "row": 11
      }
    ],
    "images": [
      {
        "src": "assets/image173.png",
        "row": 6
      }
    ]
  },
  "overview": {
    "id": "article1-16",
    "title": "Pendulum X 與 D-Cyber 有何分別？",
    "gid": 1759783696,
    "row": 16,
    "paragraphs": [
      {
        "text": "Whatsapp資訊頻道",
        "row": 16
      },
      {
        "text": "前言",
        "row": 17
      },
      {
        "text": "台灣Line社群：數碼寶貝綜合交流空間",
        "row": 17
      },
      {
        "text": "日版Pendulum X 與 港版 D-Cyber (\"雷燈\")有何分別？",
        "row": 18
      },
      {
        "text": "D-Cyber​的遊戲內容和日本版\"Pendulum X\"相同，但亦有些差異處，以下為較重要之分別：",
        "row": 20
      },
      {
        "text": "1. [遊戲介面]",
        "row": 22
      },
      {
        "text": "D-Cyber以英文為主；PenX以部份為日文",
        "row": 22
      },
      {
        "text": "2. [外觀設計]",
        "row": 23
      },
      {
        "text": "D-Cyber參考了香港授權同名漫畫​​故事中\"雷燈暴龍機\"設計",
        "row": 23
      },
      {
        "text": "3. [對戰接口]",
        "row": 24
      },
      {
        "text": "PenX為三鐵；C-Cyber則為兩鐵(變相可與大部分暴龍機對戰)",
        "row": 24
      },
      {
        "text": "4.  [CLONE]",
        "row": 25
      },
      {
        "text": "此為D-Cyber獨有功能，可供玩家儲存最多4隻的DIGIMON",
        "row": 25
      },
      {
        "text": "https://line.me/ti/g2/eYIajLtHCn12hIQ8ilKif0i5A6GSAQDxvmDD2Q",
        "row": 25
      }
    ],
    "images": [
      {
        "src": "assets/image23.png",
        "row": 18
      }
    ]
  },
